import itertools

statements = {
    "1": "¬(A ∧ B) ↔ (¬A ∨ ¬B)",
    "2": "¬(A ∨ B) ↔ (¬A ∧ ¬B)",
    "3": "(A → B) ↔ (¬B → ¬A)",
    "4": "(A → B) ↔ (¬A ∨ B)",
    "5": "(¬A → B) ↔ (A ∨ ¬B)",
    "6": "¬(A → B) ↔ (A ∧ ¬B)"
}

def eval_expr(A,B,num):
    if num=="1":
        return (not (A and B)) == ((not A) or (not B))
    if num=="2":
        return (not (A or B)) == ((not A) and (not B))
    if num=="3":
        return ((not A) or B) == ((not (not B)) or (not A))  # A->B = ¬A∨B; ¬B->¬A = B∨¬A
    if num=="4":
        return ((not A) or B) == ((not A) or B)
    if num=="5":
        # ¬A -> B = A ∨ B ; right = A ∨ ¬B
        return (A or B) == (A or (not B))
    if num=="6":
        return (not ((not A) or B)) == (A and (not B))

for num in statements:
    results=[]
    for A,B in itertools.product([True,False], repeat=2):
        results.append(eval_expr(A,B,num))
    print(num, statements[num], results, all(results))
